def is_prime(k):
    if k < 2:
        return False
    for i in range(2, int(k**0.5) + 1):
        if k % i == 0:
            return False
    return True

count = 0
# Search for primes n such that 5 <= n < 200 and gcd(n, 6) = 1 (which is true for primes > 3)
for n in range(5, 200):
    if is_prime(n):
        count += 1

print(f"Number of primes n such that 5 <= n < 200: {count}")

def is_coprime_to_6(n):
    return n % 2 != 0 and n % 3 != 0

# Count positive integers n >= 2 and n < 200 relatively prime to 6
count = 0
for n in range(2, 200):
    if is_coprime_to_6(n):
        count += 1

# List primes less than 200 and coprime to 6 (all primes > 3)
primes = []
for n in range(5, 200):
    is_prime = True
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            is_prime = False
            break
    if is_prime and is_coprime_to_6(n):
        primes.append(n)

print(f"Total candidates (coprime to 6): {count}")
print(f"Number of primes > 3: {len(primes)}")
